#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <assert.h>
#include <libtpms/tpm_types.h>
#include <libtpms/tpm_library.h>
#include <libtpms/tpm_error.h>
#include <libtpms/tpm_memory.h>
#include <libtpms/tpm_nvfilename.h>

static unsigned char *permall;
static uint32_t permall_length;

static TPM_RESULT mytpm_io_init(void){return TPM_SUCCESS;}
static TPM_RESULT mytpm_io_getlocality(TPM_MODIFIER_INDICATOR *l,uint32_t n){*l=0;return TPM_SUCCESS;}
static TPM_RESULT mytpm_io_getphysicalpresence(TPM_BOOL *p,uint32_t n){*p=FALSE;return TPM_SUCCESS;}
static TPM_RESULT mytpm_nvram_loaddata(unsigned char **d,uint32_t *l,uint32_t n,const char *name){
    if(!strcmp(name,TPM_PERMANENT_ALL_NAME)){ if(permall){*d=NULL;assert(TPM_Malloc(d,permall_length)==TPM_SUCCESS);memcpy(*d,permall,permall_length);*l=permall_length;return TPM_SUCCESS;}}
    return TPM_RETRY;
}
static TPM_RESULT mytpm_nvram_storedata(const unsigned char *d,uint32_t l,uint32_t n,const char *name){
    if(!strcmp(name,TPM_PERMANENT_ALL_NAME)){free(permall);permall=NULL;assert(TPM_Malloc(&permall,l)==TPM_SUCCESS);memcpy(permall,d,l);permall_length=l;}
    return TPM_SUCCESS;
}

int main(int argc, char**argv){
    FILE *f=fopen(argv[1],"rb"); fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    unsigned char *data=malloc(sz); fread(data,1,sz,f); fclose(f);
    unsigned char *rbuffer=NULL; uint32_t rlength,rtotal=0; TPM_RESULT res;
    unsigned char *vol_buffer=NULL; uint32_t vol_buffer_len;
    unsigned char *perm_buffer=NULL; uint32_t perm_buffer_len;
    unsigned char startup[]={0x80,0x01,0x00,0x00,0x00,0x0c,0x00,0x00,0x01,0x44,0x00,0x00};
    struct libtpms_callbacks cbs={.sizeOfStruct=sizeof(struct libtpms_callbacks),.tpm_nvram_init=NULL,.tpm_nvram_loaddata=mytpm_nvram_loaddata,.tpm_nvram_storedata=mytpm_nvram_storedata,.tpm_nvram_deletename=NULL,.tpm_io_init=mytpm_io_init,.tpm_io_getlocality=mytpm_io_getlocality,.tpm_io_getphysicalpresence=mytpm_io_getphysicalpresence};
    TPMLIB_RegisterCallbacks(&cbs);
    TPMLIB_ChooseTPMVersion(TPMLIB_TPM_VERSION_2);
    TPMLIB_MainInit();
    res=TPMLIB_Process(&rbuffer,&rlength,&rtotal,startup,sizeof(startup));
    printf("startup res=%d\n",res);
    res=TPMLIB_Process(&rbuffer,&rlength,&rtotal,data,sz);
    printf("cmd res=%d rlength=%u\n",res,rlength);
    for(unsigned i=0;i<rlength;i++) printf("%02x",rbuffer[i]);
    printf("\n");
    res=TPMLIB_GetState(TPMLIB_STATE_VOLATILE,&vol_buffer,&vol_buffer_len);
    printf("getstate volatile res=%d\n",res);
    res=TPMLIB_GetState(TPMLIB_STATE_PERMANENT,&perm_buffer,&perm_buffer_len);
    printf("getstate permanent res=%d len=%u\n",res,perm_buffer_len);
    TPMLIB_Terminate();
    return 0;
}
EOF
